<style>
.xd5-page .tc-contact-page{--tc-accent:#d32b23;padding:0 0 80px;background:#101012;color:#f7f7f8;font-family:"Segoe UI",Arial,sans-serif}
.xd5-page .tc-contact-container{width:min(1240px,calc(100% - 64px))}
.xd5-page .tc-contact-breadcrumb{padding:28px 0;color:#aeb0b9}
.xd5-page .tc-contact-breadcrumb a{color:#d6d7dc}
.xd5-page .tc-contact-heading{max-width:800px;padding:16px 0 40px}
.xd5-page .tc-contact-heading>span{display:inline-flex;align-items:center;gap:12px;color:#ff827b;font-size:12px;font-weight:700;letter-spacing:.08em;text-transform:uppercase}
.xd5-page .tc-contact-heading>span:before{content:"";width:28px;height:3px;background:#ff3b30}
.xd5-page .tc-contact-heading h1{color:#fff;font-size:clamp(36px,4vw,56px);font-weight:700;line-height:1.15;letter-spacing:-.025em;margin:14px 0 18px}
.xd5-page .tc-contact-heading p{max-width:650px;color:#c3c3ca;font-size:16px;line-height:1.8}
.xd5-page .tc-contact-layout{grid-template-columns:minmax(0,.85fr) minmax(0,1.25fr);gap:32px;align-items:stretch}
.xd5-page .tc-contact-info{padding:36px;background:#1b1b20;border:1px solid #333339;border-radius:12px;color:#fff}
.xd5-page .tc-contact-layout h2{font-size:25px;font-weight:700;line-height:1.4;margin:0 0 12px}
.xd5-page .tc-contact-info h2{color:#fff}
.xd5-page .tc-contact-info>p{color:#c3c3ca;font-size:14px;line-height:1.8;margin-bottom:30px}
.xd5-page .tc-contact-item{gap:18px;padding:24px 0;border-color:#38383f}
.xd5-page .tc-contact-item>.tc-contact-icon{flex-basis:46px;height:46px;border-radius:8px;background:#302026;color:#ff827b}
.xd5-page .tc-contact-item h3{font-size:12px;font-weight:500;color:#b9bbc5;margin-bottom:6px}
.xd5-page .tc-contact-item p,.xd5-page .tc-contact-item a{color:#f7f7f8;font-size:15px;line-height:1.8}
.xd5-page .tc-contact-item .tc-contact-directions{color:#ff827b;font-size:13px}
.xd5-page .tc-contact-form-card{padding:36px;background:#fff;border:0;border-top:4px solid #d32b23;border-radius:12px;color:#202126;box-shadow:0 20px 50px #00000020}
.xd5-page .tc-contact-form-card h2{color:#202126}
.xd5-page .tc-contact-form-card>p{color:#5c6069;font-size:14px;margin-bottom:28px}
.xd5-page .tc-contact-fields{gap:20px}
.xd5-page .tc-contact-fields label{color:#292b32;font-size:13px;font-weight:600}
.xd5-page .tc-contact-fields input,.xd5-page .tc-contact-fields textarea{background:#fafafa;border:1px solid #c9cbd2;border-radius:6px;color:#202126;font-family:inherit;font-size:15px;padding:12px 14px}
.xd5-page .tc-contact-fields input{min-height:48px}
.xd5-page .tc-contact-fields textarea{min-height:140px}
.xd5-page .tc-contact-fields small{color:#5c6069;font-size:12px}
.xd5-page .tc-contact-fields [aria-invalid=true]{border-color:#b82b23}
.xd5-page .tc-contact-form-card button{width:100%;min-height:50px;border-radius:6px;background:#d32b23;color:#fff;font-family:inherit;font-size:15px;font-weight:700;margin-top:24px;padding:14px 24px}
.xd5-page .tc-contact-form-card button:hover{background:#b8221c}
.xd5-page .tc-contact-form-card button:disabled{opacity:.7;cursor:wait}
.xd5-page .tc-contact-copy{color:#c3c3ca}
.xd5-page .tc-contact-copy h1,.xd5-page .tc-contact-copy h2,.xd5-page .tc-contact-copy h3{color:#fff}
.xd5-page .tc-contact-page a:hover{text-decoration:underline;text-underline-offset:4px}
@media(max-width:800px){.xd5-page .tc-contact-layout{grid-template-columns:minmax(0,1fr);gap:24px}.xd5-page .tc-contact-info,.xd5-page .tc-contact-form-card{padding:28px}.xd5-page .tc-contact-heading{padding-bottom:32px}}
@media(max-width:480px){.xd5-page .tc-contact-container{width:calc(100% - 32px)}.xd5-page .tc-contact-page{padding-bottom:40px}.xd5-page .tc-contact-breadcrumb{padding:20px 0}.xd5-page .tc-contact-heading{padding-top:8px}.xd5-page .tc-contact-heading h1{font-size:36px}.xd5-page .tc-contact-heading p{font-size:15px}.xd5-page .tc-contact-info,.xd5-page .tc-contact-form-card{padding:24px 20px}.xd5-page .tc-contact-layout h2{font-size:23px}.xd5-page .tc-contact-fields{grid-template-columns:minmax(0,1fr);gap:16px}}
</style>
